import csv
import io
import json
import unittest
from exporter import export_rows

FIXTURE = "fixtures/incident-17.json"


def as_rows(csv_text):
    return list(csv.reader(io.StringIO(csv_text)))


class ExportTests(unittest.TestCase):
    def test_header(self):
        self.assertTrue(export_rows([]).startswith("customer_id,region"))

    def test_headered_has_only_columns(self):
        self.assertEqual(["customer_id", "region"], list(csv.reader(io.StringIO(export_rows([]))))[0])

    def test_batch_envelope_matches_fixture(self):
        with open(FIXTURE) as fh:
            incident = json.load(fh)
        expected = incident["expected_csv"]
        self.assertEqual(expected, export_rows(incident["input"]))
        self.assertEqual(expected, export_rows(incident["input"]["payload"]["customers"]))

    def test_batch_envelope_null_export(self):
        batch = {"payload": {"customers": []}}
        self.assertEqual("customer_id,region\r\n", export_rows(batch))

    def test_batch_envelope_equals_plain_rows(self):
        rows = [
            {"customer_id": "0012", "region": "EU"},
            {"customer_id": "0070", "region": "APAC"},
        ]
        batch = {"payload": {"customers": rows}}
        self.assertEqual(as_rows(export_rows(batch)), as_rows(export_rows(rows)))

if __name__ == "__main__":
    unittest.main()

